const parse = (value) => {
  if (typeof value !== 'string') return value ?? {};
  try { return JSON.parse(value); } catch { return {}; }
};
const clean = (value, limit) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, limit);
const input = items[0]?.json ?? {};
const body = parse(input.body ?? input);
const text = clean(body.text ?? body.friction ?? body.annoyance, 600);
if (!text) throw new Error('friction text is required');

const context = clean(body.context, 300);
const impact = ['low', 'medium', 'high'].includes(body.impact) ? body.impact : 'medium';
const normalized = text.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 180);
const rules = [
  ['automation', ['repeat', 'again', 'manual', 'copy', 'paste', 'remind', 'every time', 'workflow']],
  ['config', ['nix', 'config', 'setting', 'dotfile', 'package', 'terminal', 'shell', 'desktop', 'software']],
  ['purchase', ['buy', 'replace', 'broken', 'cable', 'adapter', 'battery', 'chair', 'desk', 'hardware']],
  ['habit', ['forget', 'late', 'sleep', 'routine', 'procrastinat', 'doomscroll', 'distract', 'avoid']],
];
const scores = rules.map(([type, words]) => ({
  type,
  score: words.reduce((total, word) => total + (normalized.includes(word) ? 1 : 0), 0),
})).sort((a, b) => b.score - a.score);
const type = scores[0].score > 0 ? scores[0].type : 'investigation';
const nextSteps = {
  automation: 'Observe inputs and outputs once, then automate the smallest deterministic step.',
  config: 'Find the owning declarative option and remove the recurring manual state.',
  purchase: 'Price the replacement against time already lost; set a decision threshold.',
  habit: 'Change the trigger or environment before adding another reminder.',
  investigation: 'Capture one more occurrence with context, then identify the common cause.',
};

const now = new Date().toISOString();
const state = $getWorkflowStaticData('global');
const records = Array.isArray(state.friction) ? state.friction : [];
let record = records.find((entry) => entry.key === normalized);
if (record) {
  record.count = Number(record.count ?? 0) + 1;
  record.lastSeen = now;
  record.text = text;
  record.context = context || record.context;
  record.impact = impact;
  record.type = type;
} else {
  record = { key: normalized, text, context, impact, type, count: 1, firstSeen: now, lastSeen: now };
  records.push(record);
}
state.friction = records
  .sort((a, b) => String(b.lastSeen).localeCompare(String(a.lastSeen)))
  .slice(0, 100);

if (![3, 6, 10].includes(record.count)) return [];
const safe = (value) => clean(value, 1000).replaceAll('@', '@\u200b') || 'Not supplied.';
return [{ json: {
  discordEmbed: {
    title: `Friction graduated: ${record.type}`,
    description: safe(record.text),
    color: record.impact === 'high' ? 0xf38ba8 : record.impact === 'low' ? 0xa6e3a1 : 0xf9e2af,
    fields: [
      { name: 'Signal', value: `Seen **${record.count} times** since ${record.firstSeen.slice(0, 10)}\nImpact: **${record.impact}**`, inline: true },
      { name: 'Candidate', value: `**${record.type}**`, inline: true },
      { name: 'Context', value: safe(record.context) },
      { name: 'Smallest next move', value: nextSteps[record.type] },
    ],
    footer: { text: 'Loom friction-to-fix' },
    timestamp: now,
  },
} }];
